                                            fill="#FAAD1A" />
                                    </svg>
                                    <span class="ms-2 inline-flex">What kind of jobs can I get after completing this
                                        program?</span>
                                </button>
                            </div>
                            <div id="collapsea5" class="accordion-collapse collapse"
                                data-bs-parent="#accordionExample2">
                                <div class="accordion-body">
                                    Graduates are placed in roles like Embedded Systems Engineer, Firmware Developer,
                                    IoT Solutions Architect, Edge AI Engineer, and RTOS Developer. Our alumni work at
                                    semiconductor companies, automotive OEMs, industrial automation firms, and IoT
                                    product startups. A portfolio of real device projects sets you apart in every
                                    interview.
                                </div>
                            </div>
                        </div>

                        <!-- FAQ 6 -->
                        <div class="accordion-item">
                            <div class="accordion-header">
                                <button class="accordion-button collapsed" type="button" data-bs-toggle="collapse"
