                                            fill="#FAAD1A" />
                                    </svg>
                                    <span class="ms-2 inline-flex">How long is the program and how many hours per
                                        week?</span>
                                </button>
                            </div>
                            <div id="collapsea6" class="accordion-collapse collapse"
                                data-bs-parent="#accordionExample2">
                                <div class="accordion-body">
                                    The full program runs for 6 months, covering 24 modules across embedded systems,
                                    IoT, and AI. Expect to commit around 15–20 hours per week — including live sessions,
                                    lab work, and mini projects. It's intensive by design: real skills require real time
                                    investment.
                                </div>
                            </div>
                        </div>

                        <!-- FAQ 7 -->
                        <div class="accordion-item">
                            <div class="accordion-header">
