    <script>
        window.requestIdleCallback = window.requestIdleCallback || function (cb) { return setTimeout(cb, 1); };

        requestIdleCallback(() => {
            const swiperScript = document.createElement("script");
            swiperScript.src = "https://cdn.jsdelivr.net/npm/swiper@10/swiper-bundle.min.js";

            swiperScript.onload = () => {

                // ===== 1. Scroll Header Swiper =====
                const swiperContainer = document.querySelector(".scrollHeaderSwiper .swiper-wrapper");
                if (swiperContainer) {
                    const slides = swiperContainer.querySelectorAll(".swiper-slide");
                    if (slides.length < 4) {
                        const needed = 4 - slides.length;
                        for (let i = 0; i < needed; i++) {
                            swiperContainer.appendChild(slides[i % slides.length].cloneNode(true));
                        }
                    }
                    const swiperHeader = new Swiper(".scrollHeaderSwiper", {
                        slidesPerView: "auto",
                        loop: true,
                        speed: 6000,
                        autoplay: { delay: 0, disableOnInteraction: false },
                        allowTouchMove: false,
                    });
                    const swiperEl = document.querySelector(".scrollHeaderSwiper");
                    swiperEl.addEventListener("mouseenter", () => swiperHeader.autoplay.stop());
                    swiperEl.addEventListener("mouseleave", () => swiperHeader.autoplay.start());
                }

                // ===== 2. Strip Ticker Swiper ✅ =====
                const stripContainer = document.querySelector(".stripTickerSwiper .swiper-wrapper");
                if (stripContainer) {
                    const stripSlides = stripContainer.querySelectorAll(".swiper-slide");
                    // Kam se kam 6 slides chahiye smooth loop ke liye
                    if (stripSlides.length < 6) {
                        const needed = 6 - stripSlides.length;
                        const fragment = document.createDocumentFragment();
                        for (let i = 0; i < needed; i++) {
                            fragment.appendChild(stripSlides[i % stripSlides.length].cloneNode(true));
                        }
                        stripContainer.appendChild(fragment);
                    }
                    new Swiper(".stripTickerSwiper", {
                        slidesPerView: "auto",
                        loop: true,
                        speed: 4000,
                        autoplay: { delay: 0, disableOnInteraction: false },
                        allowTouchMove: false,
                    });
                }
                // ===== Certificate Swiper =====
                if (document.querySelector(".mySwiper6")) {
                    new Swiper(".mySwiper6", {
                        slidesPerView: 1,
                        spaceBetween: 0,
                        loop: false,
                        freeMode: false,
                        autoplay: false,
                        navigation: {
                            nextEl: ".swiper-button-next6",
                            prevEl: ".swiper-button-prev6",
                        },
                    });
                }
                // ===== 3. All Other Swipers =====
                const configs = {
                    mySwiper1: 3,
                    mySwiper2: 2,
                    mySwiper4: 2,
                    mySwiper5: 3,
                };

                Object.entries(configs).forEach(([className, slidesView]) => {
                    if (!document.querySelector(`.${className}`)) return;

                    new Swiper(`.${className}`, {
                        slidesPerView: slidesView,
                        spaceBetween: 30,
                        loop: className === "mySwiper2" ? false : true,
                        freeMode: true,
                        breakpoints: {
                            280: { slidesPerView: 1, spaceBetween: 10 },
                            320: { slidesPerView: 1, spaceBetween: 10 },
                            480: { slidesPerView: 2, spaceBetween: 10 },
                            768: {
                                slidesPerView: className === "mySwiper1" ? 2 : className === "mySwiper2" ? 3 : slidesView,
                                spaceBetween: 10,
                            },
                            992: { slidesPerView: slidesView, spaceBetween: 10 },
                            1200: { slidesPerView: slidesView, spaceBetween: 20 },
                        },
                        autoplay: className === "mySwiper2" ? false : {
                            delay: 3500,
                            disableOnInteraction: true,
                            pauseOnMouseEnter: true,
                        },
                        navigation: {
                            nextEl: `.swiper-button-next${className.slice(-1)}`,
                            prevEl: `.swiper-button-prev${className.slice(-1)}`,
                        },
                        pagination: {
                            el: `.swiper-pagination${className.slice(-1)}`,
                            clickable: true,
                        },
                    });
                });
            };

            document.body.appendChild(swiperScript);
        });
    </script>

    <script defer>
        function getTimeRemaining(endTime) {
            const total = Date.parse(endTime) - Date.parse(new Date());
            const seconds = Math.floor((total / 1000) % 60);
            const minutes = Math.floor((total / 1000 / 60) % 60);
            const hours = Math.floor((total / (1000 * 60 * 60)) % 24);
            const days = Math.floor(total / (1000 * 60 * 60 * 24));

            return {
                total,
                days,
                hours,
                minutes,
                seconds
            };
        }

        function getEndTime() {
            return new Date(2026, 4, 20, 23, 59, 59); // 20 May 2026
